#include <vector>
#include <cstddef>
#include <limits>
#include <omp.h>

size_t findFirstEven(std::vector<int> const& x) {
    const size_t n = x.size();
    if (n == 0) return n; // not found

    size_t global_min = n;

    #pragma omp parallel
    {
        size_t local_min = n;

        #pragma omp for nowait
        for (size_t i = 0; i < n; ++i) {
            if ((x[i] % 2) == 0) {
                if (i < local_min) local_min = i;
            }
        }

        #pragma omp critical
        {
            if (local_min < global_min) global_min = local_min;
        }
    }

    return global_min; // returns n if no even number exists
}
